import{_ as o,C as r,o as s,c as i,a2 as a,b as l,w as n,a as p,E as d,a3 as h}from"./chunks/framework.BC3NdntU.js";const m=JSON.parse('{"title":"11.4 上下文工程(Context / 记忆 / 压缩 / RAG)","description":"","frontmatter":{},"headers":[],"relativePath":"卷十一-AIAgentHarness与提示词工程/11.4-上下文工程.md","filePath":"卷十一-AIAgentHarness与提示词工程/11.4-上下文工程.md","lastUpdated":1788918302000}'),u={name:"卷十一-AIAgentHarness与提示词工程/11.4-上下文工程.md"};function g(c,t,E,A,b,k){const e=r("Mermaid");return s(),i("div",null,[t[1]||(t[1]=a('<h1 id="_11-4-上下文工程-context-记忆-压缩-rag" tabindex="-1">11.4 上下文工程(Context / 记忆 / 压缩 / RAG) <a class="header-anchor" href="#_11-4-上下文工程-context-记忆-压缩-rag" aria-label="Permalink to &quot;11.4 上下文工程(Context / 记忆 / 压缩 / RAG)&quot;">​</a></h1><blockquote><p>卷:卷十一 · AI Agent Harness 与提示词工程 阅读时间:30min</p></blockquote><hr><h2 id="引言-上下文窗口有限-该放什么-是核心工程问题" tabindex="-1">引言:上下文窗口有限,&quot;该放什么&quot;是核心工程问题 <a class="header-anchor" href="#引言-上下文窗口有限-该放什么-是核心工程问题" aria-label="Permalink to &quot;引言:上下文窗口有限,&quot;该放什么&quot;是核心工程问题&quot;">​</a></h2><p>LLM 一切能力建立在上下文之上,但窗口<strong>有限</strong>。上下文工程要回答的是:<strong>在有限窗口里,放哪些内容、以什么结构、按什么顺序,才能让 Agent 最优达成目标。</strong></p><hr><h2 id="一、上下文是-稀缺资源" tabindex="-1">一、上下文是&quot;稀缺资源&quot; <a class="header-anchor" href="#一、上下文是-稀缺资源" aria-label="Permalink to &quot;一、上下文是&quot;稀缺资源&quot;&quot;">​</a></h2><p>OpenAI harness-engineering 博客反复强调:</p><blockquote><p><strong>&quot;情境是一种稀缺资源。一个巨大的指令文件会挤掉任务、代码和相关文档——智能体要么会错过关键约束,要么开始针对错误的约束优化。&quot;</strong></p></blockquote><p>窗口是硬约束,放多了挤掉关键信息,放少了能力不够。&quot;塞什么&quot;本身就是最高层设计决策。</p><p><strong>上下文组成:</strong></p>',11)),(s(),l(h,null,{default:n(()=>[d(e,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E4%B8%8A%E4%B8%8B%E6%96%87%20Context%5D%20--%3E%20B%5BSystem%20Prompt%20%E8%A7%92%E8%89%B2%2F%E7%BA%A6%E6%9D%9F%5D%0A%20%20%20%20A%20--%3E%20C%5B%E4%BB%BB%E5%8A%A1%E7%9B%AE%E6%A0%87%20%E7%94%A8%E6%88%B7%E6%84%8F%E5%9B%BE%5D%0A%20%20%20%20A%20--%3E%20D%5B%E5%8E%86%E5%8F%B2%E6%B6%88%E6%81%AF%20%E5%AF%B9%E8%AF%9D%2F%E5%8A%A8%E4%BD%9C%2F%E8%A7%82%E5%AF%9F%5D%0A%20%20%20%20A%20--%3E%20E%5B%E5%B7%A5%E5%85%B7%E7%BB%93%E6%9E%9C%20%E6%A3%80%E7%B4%A2%E7%89%87%E6%AE%B5%2F%E6%89%A7%E8%A1%8C%E8%BE%93%E5%87%BA%5D%0A%20%20%20%20A%20--%3E%20F%5B%E5%A4%96%E9%83%A8%E8%AE%B0%E5%BF%86%20%E9%95%BF%E6%9C%9F%E7%9F%A5%E8%AF%86%2F%E6%96%87%E6%A1%A3%5D%0A"})]),fallback:n(()=>[...t[0]||(t[0]=[p(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a(`<hr><h2 id="二、核心原则-地图-而不是说明书" tabindex="-1">二、核心原则:地图,而不是说明书 <a class="header-anchor" href="#二、核心原则-地图-而不是说明书" aria-label="Permalink to &quot;二、核心原则:地图,而不是说明书&quot;">​</a></h2><blockquote><p><strong>&quot;给 Codex 的是一张地图,而不是一本 1000 页的说明书。&quot;</strong></p></blockquote><p>巨大 AGENTS.md 失败的四个原因(精辟):</p><ol><li><strong>挤占窗口</strong> → 错过关键约束</li><li><strong>过多指导反无效</strong> → &quot;一切都重要=一切都不重要&quot;→ 模式匹配而非导航</li><li><strong>立即腐烂</strong> → 过时规则的坟场</li><li><strong>难以核实</strong> → 大 blob 无法机械检查 → 漂移</li></ol><p><strong>正确做法:渐进式披露(Progressive Disclosure)</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个小而稳的入口(地图,~100 行)</span></span>
<span class="line"><span>        ↓ 指向</span></span>
<span class="line"><span>更深层信息源(docs/ 结构化目录,按需查)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr><h2 id="三、-不在上下文里的东西-不存在" tabindex="-1">三、&quot;不在上下文里的东西 = 不存在&quot; <a class="header-anchor" href="#三、-不在上下文里的东西-不存在" aria-label="Permalink to &quot;三、&quot;不在上下文里的东西 = 不存在&quot;&quot;">​</a></h2><blockquote><p><strong>&quot;从智能体角度来看,它在运行时无法在上下文中访问的任何内容,都是不存在的。&quot;</strong></p></blockquote><ul><li>你脑子里、聊天记录、Google Docs 里的知识,Agent <strong>统统看不见</strong></li><li>只有<strong>喂进上下文</strong>的,才是它可用的世界</li><li>所以要把隐性知识<strong>显性化、结构化、放进它能访问的地方</strong>(仓库/docs/schema)——&quot;仓库作为记录系统&quot;</li></ul><hr><h2 id="四、记忆三形态" tabindex="-1">四、记忆三形态 <a class="header-anchor" href="#四、记忆三形态" aria-label="Permalink to &quot;四、记忆三形态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>存什么</th><th>实现</th></tr></thead><tbody><tr><td>工作记忆</td><td>本轮对话/动作/观察</td><td>直接放上下文</td></tr><tr><td>短期/会话</td><td>多轮历史</td><td>上下文 + 会话存储</td></tr><tr><td><strong>长期记忆</strong></td><td>跨会话知识/偏好</td><td>向量库/文档(RAG,检索增强生成)</td></tr></tbody></table><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">relevant </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> vector_db.search(query, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">top_k</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># RAG:用时按相关度捞进上下文</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">context </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> system </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> relevant </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user_question</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p>为什么检索而非全塞?窗口有限 + 相关性。RAG 精髓 = &quot;<strong>用时按需检索</strong>&quot;,是&quot;地图而非说明书&quot;在知识上的延伸。</p></blockquote><hr><h2 id="五、压缩与裁剪" tabindex="-1">五、压缩与裁剪 <a class="header-anchor" href="#五、压缩与裁剪" aria-label="Permalink to &quot;五、压缩与裁剪&quot;">​</a></h2><table tabindex="0"><thead><tr><th>手段</th><th>说明</th></tr></thead><tbody><tr><td>摘要压缩</td><td>完成步骤压缩成纪要</td></tr><tr><td>滑动窗口</td><td>只留最近 N 条</td></tr><tr><td>选择性保留</td><td>关键结论/决策/报错留原文</td></tr><tr><td>分级模型</td><td>便宜模型先摘要</td></tr></tbody></table><blockquote><p>原则:<strong>保留&quot;决策与结论&quot;,裁剪&quot;过程噪音&quot;</strong>。</p></blockquote><hr><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上下文工程 = 有限窗口里决定&quot;放什么、怎么组织、顺序&quot;</span></span>
<span class="line"><span>原则:上下文稀缺 / 地图而非说明书(渐进式披露)/ 不在上下文=不存在 / 记忆三层 / 压缩裁剪</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><hr><h2 id="七、思考题" tabindex="-1">七、思考题 <a class="header-anchor" href="#七、思考题" aria-label="Permalink to &quot;七、思考题&quot;">​</a></h2><p><strong>Q1:为什么&quot;一个巨大的指令文件&quot;对 Agent 是反效果?</strong></p><p>它<strong>挤占有限窗口</strong>(挤掉任务与代码)、<strong>稀释注意力</strong>(什么都重要=什么都不重要)、<strong>容易腐烂</strong>(过时规则堆成坟场)、<strong>难核实</strong>(大 blob 无法机械检查漂移)。要用&quot;地图 + 渐进式披露&quot;。</p><p><strong>Q2:如何给 Agent 设计&quot;长期记忆&quot;?</strong></p><p>把知识<strong>结构化、可检索地</strong>存起来(向量库/文档/数据库),用时<strong>按相关性检索 top-k 进上下文</strong>(RAG),而非全塞。配合&quot;仓库作为记录系统&quot;:决策/计划/文档版本化沉淀,Agent 用工具查。</p><p><strong>Q3:什么是&quot;渐进式披露&quot;?为什么优于&quot;一上来全塞&quot;?</strong></p><p>先给一个小而稳的入口(地图),再让 Agent <strong>按需去查</strong>更深层信息。优于全量灌注:不挤窗口、不稀释注意力、不易腐烂、可逐步核责。</p><p><strong>Q4:&quot;不在上下文的 = 不存在&quot;这句话的含义与工程启示?</strong></p><p>Agent 只能看到喂进上下文的内容,你脑子里/Slack/文档里的它都看不见。启示:<strong>把隐性知识显性化、结构化地沉淀到它可读的地方</strong>(仓库/docs/schema)。</p><p><strong>Q5:记忆三层各是什么?RAG 属于哪层?</strong></p><p>工作记忆(本轮)、短期/会话记忆(一任务)、<strong>长期记忆</strong>(跨会话知识)。RAG 属于长期记忆——知识入库,用时按相关度检索进上下文。</p><p><strong>Q6:上下文&quot;压缩/裁剪&quot;的原则?</strong></p><p><strong>保留决策与结论,裁掉过程噪音</strong>:已完成的步骤摘要化、滑动窗口只留最近、关键结论/报错保留原文。它决定任务能走多远而不崩、不贵。</p><hr><p>📎 参考:OpenAI《harness-engineering》博客、Anthropic《Building Effective Agents》、LangChain Memory/RAG 文档</p>`,39))])}const _=o(u,[["render",g]]);export{m as __pageData,_ as default};
